import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])

    # Fenwick Tree implementation
    fenwick = [0] * (n + 2)
    arr = [1] * (n + 2)  # 1-indexed, initialize with 1

    def fenwick_update(idx, delta):
        while idx <= n + 1:
            fenwick[idx] += delta
            idx += idx & (-idx)

    def fenwick_query(idx):
        result = 0
        while idx > 0:
            result += fenwick[idx]
            idx -= idx & (-idx)
        return result

    def range_sum(l, r):
        if l > r:
            return 0
        return fenwick_query(r + 1) - fenwick_query(l)

    def range_update(l, r, delta):
        if l > r:
            return
        fenwick_update(l + 1, delta)
        if r + 2 <= n + 1:
            fenwick_update(r + 2, -delta)

    idx = 2
    output = []

    for _ in range(q):
        op = data[idx]
        l = int(data[idx + 1])
        r = int(data[idx + 2])
        idx += 3

        if op == "QUERY":
            result = range_sum(l, r)
            output.append(str(result))
        else:
            delta = -1 if op == "ALLOCATE" else 1
            range_update(l - 1, r - 1, delta)

    print("\n".join(output))

if __name__ == "__main__":
    main()
